// SenseBook visuals. All of them come from the build chat (sensebook/design/) and are copied
// into public/design/ by scripts/sync-design.mjs. Nothing here is drawn or generated by the website.

export type RenderId =
  | "hero"
  | "front"
  | "side"
  | "top"
  | "exploded"
  | "cutaway"
  | "hardcover"
  | "paperback"
  | "tripod"
  | "folded"
  | "extended";

export type RenderAsset = {
  file: string;
  width: number;
  height: number;
  alt: string;
  caption: string;
  /** Technical plates are rendered on #F4F4F1, the same as the site’s stone, so they need no frame. */
  plate?: boolean;
};

